const body = $input.first().json.body || $input.first().json;

const validModes = ['player_article','game_recap','event_standouts','team_story','recruiting_report','recruiting_summary'];
const rawMode = (body.mode || 'player_article').trim().toLowerCase().replace(/[\s-]/g,'_');
const normalizedMode = rawMode === 'recruiting_summary' ? 'recruiting_report' : rawMode;
const mode = validModes.includes(normalizedMode) ? normalizedMode : 'player_article';
const modeLabels = {
  player_article:    'Player Feature Article',
  game_recap:        'Game Recap',
  event_standouts:   'Event Standouts',
  team_story:        'Team Story',
  recruiting_report: 'Recruiting Report'
};

const validPresets = ['Neutral Reporter','Recruiting Analyst','Scouting Breakdown','Event Recap','Player Spotlight','High-Energy Feature','Feature Story','Professional Media','Shortform Social','Development-Focused','Coach/Recruiter Brief'];
const rawPreset = (body.style_preset || 'Neutral Reporter').trim();
const stylePreset = validPresets.includes(rawPreset) ? rawPreset : 'Neutral Reporter';

const validTones = ['analytical','narrative','energetic','neutral','technical','inspirational'];
const tone = validTones.includes((body.tone||'').toLowerCase()) ? body.tone.toLowerCase() : 'analytical';

const validAudiences = ['general_public','college_recruiters','coaches','parents_players','media_press','social_media'];
const rawAud = (body.audience||'general_public').toLowerCase().replace(/[\s-]/g,'_');
const audience = validAudiences.includes(rawAud) ? rawAud : 'general_public';
const audienceLabels = {
  general_public:   'General Sports Audience',
  college_recruiters:'College Recruiters',
  coaches:          'Coaches & Staff',
  parents_players:  'Parents & Players',
  media_press:      'Media & Press',
  social_media:     'Social Media'
};

const validConf = ['high','moderate','measured','cautious'];
const confidence = validConf.includes((body.confidence||'').toLowerCase()) ? body.confidence.toLowerCase() : 'moderate';

const validAngles = ['breakout_performance','defensive_impact','clutch_performance','floor_general_leadership','shooting_showcase','two_way_player'];
const rawAngle = (body.primary_angle || 'breakout_performance').toLowerCase().replace(/[\s-]/g,'_');
const primaryAngle = validAngles.includes(rawAngle) ? rawAngle : 'breakout_performance';

const rawWC = parseInt(body.word_count) || 350;
const wordCount = Math.min(Math.max(rawWC, 80), 800);

const playerName   = (body.player_name     || '').trim();
const position     = (body.position        || '').trim();
const team         = (body.team            || '').trim();
const ageGrade     = (body.age_grade       || '').trim();
const eventName    = (body.event_name      || '').trim();
const evalNotes    = (body.evaluator_notes || '').trim();
const gameNotes    = (body.game_notes      || '').trim();
const teamNotes    = (body.team_notes      || '').trim();
const standoutTags = Array.isArray(body.standout_tags) ? body.standout_tags : [];
const sliders      = body.sliders && typeof body.sliders === 'object' ? body.sliders : {};
const styleSample  = (body.style_sample    || '').trim();
const styleSampleUrl = (body.style_sample_url || '').trim();
const serpContext = (body.serp_context || body.research_snippets || '').trim();
const validSpines = ['stakes','timeline','matchup','identity','legacy','injury_subplot'];
const rawSpine = (body.story_spine || 'stakes').trim().toLowerCase().replace(/[\s-]/g,'_');
const storySpine = validSpines.includes(rawSpine) ? rawSpine : 'stakes';
const momentAnchor1 = (body.moment_anchor_1 || '').trim();
const momentAnchor2 = (body.moment_anchor_2 || '').trim();
const momentAnchor3 = (body.moment_anchor_3 || '').trim();
const statLine = (body.stat_line || '').trim();
const verifiedFacts = (body.verified_facts || '').trim();
const quote1 = (body.quote_1 || '').trim();
const quote2 = (body.quote_2 || '').trim();
const quote3 = (body.quote_3 || '').trim();
const espnDepthMode = body.espn_depth_mode === true || body.espn_depth_mode === 'true';
const clampV = (x) => Math.min(10, Math.max(1, parseInt(x, 10) || 6));
const voicePunch = clampV(body.voice_punch);
const voiceAnalyticsDensity = clampV(body.voice_analytics_density);
const voiceSceneDetail = clampV(body.voice_scene_detail);
const validQuickFormats = ['full','recap_short','preview_bullets','social_pack'];
const rawQf = (body.quick_format || 'full').trim().toLowerCase().replace(/[\s-]/g,'_');
const quickFormat = validQuickFormats.includes(rawQf) ? rawQf : 'full';
const templateContract = String(body.template_contract || '').trim();
const structuredExtras = String(body.structured_extras || '').trim();
const pubName      = (body.publication_name|| 'SportsPilot').trim();
const regenerateInstructions = (body.regenerate_instructions || body.user_edit_instructions || body.revision_instructions || '').trim();
const sectionRewrite = (body.section_rewrite || '').trim().toLowerCase();
const rewriteContent = (body.rewrite_content || '').trim();

const hasContent = evalNotes.length > 10 || gameNotes.length > 10 || teamNotes.length > 10;
if (!hasContent) throw new Error('evaluator_notes, game_notes, or team_notes is required');

const sessionId = 'CAI-' + Date.now() + '-' + Math.random().toString(36).substring(2,8).toUpperCase();

return [{
  json: {
    sessionId, mode, modeLabel: modeLabels[mode],
    stylePreset, tone, audience, audienceLabel: audienceLabels[audience],
    confidence, primaryAngle, wordCount,
    playerName, position, team, ageGrade, eventName,
    evalNotes, gameNotes, teamNotes,
    standoutTags, sliders, styleSample, styleSampleUrl, serpContext, pubName,
    storySpine, momentAnchor1, momentAnchor2, momentAnchor3,
    statLine, verifiedFacts, quote1, quote2, quote3,
    espnDepthMode, voicePunch, voiceAnalyticsDensity, voiceSceneDetail,
    quickFormat,
    templateContract, structuredExtras,
    regenerateInstructions, sectionRewrite, rewriteContent,
    timestamp: new Date().toISOString()
  }
}];

const d = $input.first().json;

function sliderSummary(sliders) {
  if (!sliders || !Object.keys(sliders).length) return '';
  const lines = Object.entries(sliders).map(([k,v]) => {
    const label = k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
    return `  ${label.padEnd(22)} ${v}/10`;
  });
  return 'EVALUATION SLIDERS:\n' + lines.join('\n');
}

const contentLines = [];
if (d.playerName) contentLines.push('Player: ' + d.playerName + (d.position ? ' — ' + d.position : '') + (d.team ? ' | ' + d.team : ''));
if (d.ageGrade)   contentLines.push('Age/Grade: ' + d.ageGrade);
if (d.eventName)  contentLines.push('Event: ' + d.eventName);
if (d.evalNotes)  contentLines.push('\nEVALUATOR NOTES (sole factual source — do not invent beyond these):\n' + d.evalNotes);
if (d.gameNotes)  contentLines.push('\nGAME NOTES:\n' + d.gameNotes);
if (d.teamNotes)  contentLines.push('\nTEAM NOTES:\n' + d.teamNotes);
const sliderText = sliderSummary(d.sliders);
if (sliderText)   contentLines.push('\n' + sliderText);
if (d.standoutTags.length) contentLines.push('\nSTANDOUT TAGS: ' + d.standoutTags.join(' · '));
if (d.serpContext && d.serpContext.length > 10) {
  contentLines.push('\nWEB RESEARCH SNIPPETS (SerpAPI — external context only; do NOT treat as verified facts unless consistent with evaluator notes):\n' + d.serpContext.slice(0, 2500));
}
if (d.styleSampleUrl && d.styleSampleUrl.length > 8) {
  contentLines.push('\nSTYLE SAMPLE SOURCE URL (reference only): ' + d.styleSampleUrl);
}
const spineGuide = {
  stakes: 'Stakes — why this moment matters for standings/postseason pressure',
  timeline: 'Timeline — how recent performances set up this game',
  matchup: 'Matchup chess — counters, adjustments, and responses',
  identity: 'Identity — role, team style, and what this performance signals',
  legacy: 'Legacy/milestone framing (ONLY if supported by notes)',
  injury_subplot: 'Availability/workload subplot (ONLY if supported by notes)'
};
if (d.storySpine && spineGuide[d.storySpine]) {
  contentLines.push('\nSTORY SPINE: ' + spineGuide[d.storySpine]);
}
if (d.momentAnchor1) contentLines.push('\nMOMENT ANCHOR 1 (use as a concrete scene beat): ' + d.momentAnchor1);
if (d.momentAnchor2) contentLines.push('\nMOMENT ANCHOR 2: ' + d.momentAnchor2);
if (d.momentAnchor3) contentLines.push('\nMOMENT ANCHOR 3: ' + d.momentAnchor3);
if (d.statLine) contentLines.push('\nSTAT LINE / BOX (treat as factual anchor — do not invent beyond notes + this block):\n' + d.statLine);
if (d.verifiedFacts) contentLines.push('\nVERIFIED FACTS:\n' + d.verifiedFacts);
if (d.quote1 || d.quote2 || d.quote3) {
  const qs = [d.quote1, d.quote2, d.quote3].filter(Boolean);
  if (qs.length) contentLines.push('\nQUOTES TO WEAVE (optional):\n' + qs.join('\n---\n'));
}
if (d.espnDepthMode) {
  const targetW = Math.max(parseInt(d.wordCount,10) || 500, 650);
  contentLines.push('\nESPN-DEPTH MODE: Target at least ' + targetW + ' words. Section budgets: lede ~80–120w; stakes/nut ~120–180w; 2–3 evidence paragraphs tied to moment anchors; closing ~60–120w with a forward look. Ban vague clichés unless tied to a specific play (e.g. avoid empty "electric", "locked in", "stepped up").');
  contentLines.push('VOICE MIX (1=subtle, 10=heavy): punch ' + (d.voicePunch||6) + '/10, analytics ' + (d.voiceAnalyticsDensity||6) + '/10, scene detail ' + (d.voiceSceneDetail||6) + '/10.');
}
const __ma = [d.momentAnchor1, d.momentAnchor2, d.momentAnchor3].filter(Boolean);
if (__ma.length) contentLines.push('\nMOMENT ANCHORS (same beats in recap, bullets, social, and longform; paraphrase; do not invent new signature moments):\n' + __ma.map((x, i) => '  ' + (i + 1) + '. ' + x).join('\n'));
if (d.templateContract) contentLines.push('\nARTICLE STRUCTURE CONTRACT (follow section order; scale per-section shares to the target word count):\n' + d.templateContract);
if (d.structuredExtras) contentLines.push('\nSTRUCTURED EXTRAS (optional mini box score, extra lines, or pasted JSON — factual only; do not extrapolate):\n' + d.structuredExtras);

const quickFmt = {
  recap_short: '\nQUICK FORMAT — SHORT RECAP (200–350 words): Write a tight newspaper-style recap. Lead with outcome and one key performer line. If MOMENT ANCHORS are listed above, preserve the same numbered beats in shorter form. 2–3 short paragraphs maximum. No betting or fantasy angles unless explicitly in evaluator or game notes. Every stat must come from source data or STRUCTURED EXTRAS.',
  preview_bullets: '\nQUICK FORMAT — PREVIEW (bullets): Write a 2–3 sentence hook, then 5–7 bullet lines. At least two bullets should map to the MOMENT ANCHORS above when present. Cover what is happening, who, stakes, one key matchup or player to watch, availability only if in notes. End with one forward-looking line. Do not invent odds, spreads, or betting lines.',
  social_pack: '\nQUICK FORMAT — SOCIAL PACK: Use these exact headers on separate lines:\nTWEET: (one line, max 280 characters)\nTHREAD 1: / THREAD 2: / THREAD 3: (each max 280 characters; omit unused thread lines)\nCAPTION 1: / CAPTION 2: / CAPTION 3: (each max 125 characters)\nTHREAD lines should echo the same story beats as MOMENT ANCHORS when listed. Facts only from source data or STRUCTURED EXTRAS; no gambling unless in notes.',
};
if (quickFmt[d.quickFormat]) contentLines.push(quickFmt[d.quickFormat]);
const contentBlock = contentLines.join('\n');

const presetGuides = {
  'Neutral Reporter':      'Objective, factual, journalistic. No opinion unless clearly attributed.',
  'Recruiting Analyst':    'Data-informed, projection-focused, coach-facing. Clinical but readable.',
  'Scouting Breakdown':    'Technical, structured, category-driven. Specific, observational, layered.',
  'Event Recap':           'Chronological flow, game-moment highlights, competitive context.',
  'Player Spotlight':      'Narrative-first, character-driven. Celebratory but grounded.',
  'High-Energy Feature':   'Bold, punchy, fast-paced. Vivid verbs. Short punchy sentences.',
  'Feature Story':         'Narrative-driven and polished, blending scene setting with insight.',
  'Professional Media':    'Polished, broadcast-quality, publication-ready.',
  'Shortform Social':      'Tight, punchy, shareable. Built for social virality.',
  'Development-Focused':   'Growth-minded, forward-looking, coachable-trait emphasis.',
  'Coach/Recruiter Brief': 'Efficient, hierarchical, time-respecting. Front-load key data.'
};
const audGuides = {
  general_public:    'Write for a broad sports fan audience. Focus on narrative and entertainment.',
  college_recruiters:'Write for college coaches. Lead with projectable skills and intangibles.',
  coaches:           'Use technical terminology. Include tactical observations and system fit.',
  parents_players:   'Encouraging, accessible tone. Celebrate effort and character.',
  media_press:       'Polished media-standard prose. Headline-friendly, quotable sentences.',
  social_media:      'Punchy, high-energy shortform designed for sharing.'
};
const confGuides = {
  high:     'Write with confident, assertive language. Use strong declarative statements.',
  moderate: 'Balance confidence with appropriate qualification. Let evidence speak.',
  measured: 'Use measured, evidence-anchored language. Qualify projections clearly.',
  cautious: 'Write conservatively. Every claim must be directly supported by notes.'
};
const styleInstruction = d.styleSample && d.styleSample.length > 50
  ? `\nSTYLE SAMPLE — ADOPT THIS WRITER'S VOICE (do NOT copy sentences, only the voice):\n---\n${d.styleSample.slice(0,1200)}\n---`
  : '';

const revisionInstruction = d.regenerateInstructions
  ? `\nREVISION REQUEST (MANDATORY):\n${d.regenerateInstructions}\n${d.rewriteContent ? `\nCURRENT ARTICLE DRAFT TO REVISE (REFERENCE):\n---\n${d.rewriteContent.slice(0,3500)}\n---` : ''}\nFollow this revision request strictly while keeping all claims grounded in source data.`
  : '';

const sharedContext = `
PUBLICATION: ${d.pubName}
ARTICLE TYPE: ${d.modeLabel}
STYLE PRESET: ${d.stylePreset} — ${presetGuides[d.stylePreset]}
TONE: ${d.tone} | AUDIENCE: ${d.audienceLabel} | CONFIDENCE: ${d.confidence}
${audGuides[d.audience]}
${confGuides[d.confidence]}${styleInstruction}${revisionInstruction}

SOURCE DATA (all facts must trace to this — do not invent):
${contentBlock}
`;

return [{ json: { ...d, contentBlock, sharedContext } }];

const d = $input.first().json;

const modeHeadlineGuides = {
  player_article:    'A specific, vivid headline that captures the player\'s defining quality. Example style: "The Floor General Nobody Saw Coming" or "Thompson\'s Vision Is Ahead of His Time."',
  game_recap:        'A headline that captures the game\'s defining moment or narrative arc.',
  event_standouts:   'A headline that captures the event\'s top story or breakout performer.',
  team_story:        'Team identity in one vivid, memorable phrase.',
  recruiting_report: 'Projection-forward. "The Point Guard Built for the Modern Game" — not generic.'
};

const systemPrompt = `You are CoverageAssistAI — Stage 1: Title, Introduction & SEO.

Your job is to produce THREE things for a sports article:
1. HEADLINE — ${modeHeadlineGuides[d.mode] || 'A compelling, specific headline.'}
2. INTRODUCTION (lede) — 2-3 sentences (~60-80 words). Open with the most memorable single moment or quality. Drop the reader into a specific scene or situation. Make them want to read the next paragraph. For a recruiting report, set the player baseline quickly and lead with the highest-value observation.
3. SEO KEYWORDS — A comma-separated list of 8-12 targeted SEO keywords/phrases relevant to this article. Include: player name, position, team, event name, relevant sports terms, and audience-specific terms (e.g. "basketball recruiting", "point guard prospect").

${d.sharedContext}

HALLUCINATION GUARD: Every factual claim must trace directly to the source data above. Do not invent stats, names, or moments.

OUTPUT FORMAT (use these exact labels, nothing else):
HEADLINE: [your headline here]

INTRODUCTION:
[your lede paragraph here]

SEO KEYWORDS:
[keyword1, keyword2, keyword3, ...]`;

const userPrompt = `Generate the Headline, Introduction, and SEO Keywords for this ${d.modeLabel} about ${d.playerName || 'the subject'} at ${d.eventName || 'the event'}.`;

return [{ json: { ...d, stage1_system: systemPrompt, stage1_user: userPrompt } }];

const upstream = $('Build Stage 1 Prompt').first().json;
const stage1Raw = $input.first().json.message?.content || $input.first().json.text || '';

const headlineMatch   = stage1Raw.match(/HEADLINE:\s*(.+?)(?=\n|$)/);
const introMatch      = stage1Raw.match(/INTRODUCTION:\s*([\s\S]+?)(?=SEO KEYWORDS:|$)/);
const seoMatch        = stage1Raw.match(/SEO KEYWORDS:\s*([\s\S]+?)$/);

const headline    = (headlineMatch?.[1]  || '').trim();
const introduction= (introMatch?.[1]     || '').trim();
const seoKeywords = (seoMatch?.[1]       || '').trim();

return [{ json: { ...upstream, stage1_raw: stage1Raw, headline, introduction, seoKeywords } }];

const upstream = $('Build Stage 2 Prompt').first().json;
const mainBody = ($input.first().json.message?.content || $input.first().json.text || '').trim();
return [{ json: { ...upstream, mainBody } }];

const d = $input.first().json;

const modeClosingGuides = {
  player_article:    'End with a MEMORABLE closing line — 1-2 sentences (~40-60 words). Should feel like the final line of a magazine feature. Leave the reader with a clear, lasting impression of who this player is and where they are headed.',
  game_recap:        'A forward-looking close — 1-2 sentences. Sets up the next game or storyline. What does this result mean for what comes next?',
  event_standouts:   'An event summary paragraph (~60 words): What did the event reveal about this class or competition level? Then a forward-looking final sentence.',
  team_story:        'A closing statement (~40-60 words) that captures the essence of this team in one memorable image or idea.',
  recruiting_report: 'Evaluator Recommendation (2-3 sentences, ~50 words): The closing verdict. Calibrated to confidence level. Should read like a scout\'s final note on a film session — actionable and specific.'
};

const systemPrompt = `You are CoverageAssistAI — Stage 3: Conclusion Writer.

You will write ONLY the conclusion/closing of a sports article. The headline, introduction, and main body have already been written.

HEADLINE: ${d.headline}

INTRODUCTION:
${d.introduction}

MAIN BODY (already written — your conclusion must flow naturally from this):
${d.mainBody}

CONCLUSION GUIDE:
${modeClosingGuides[d.mode] || modeClosingGuides['player_article']}

${d.sharedContext}

CRITICAL REQUIREMENTS:
- The conclusion must feel like a NATURAL continuation of the body above — no structural seam.
- It must be MEMORABLE. Read it and ask: does this stay with you?
- Do NOT introduce new facts or statistics that were not established in the body.
- Do NOT repeat the lede or headline sentiment verbatim — reframe and elevate.
- Calibrated to confidence level: ${d.confidence} — ${d.confidence === 'high' ? 'assertive, declarative, forward-leaning.' : d.confidence === 'cautious' ? 'evidence-anchored, conservative.' : 'balanced and evidence-grounded.'}

HALLUCINATION GUARD: Every factual claim must trace to the source data. Do not invent.

OUTPUT: Return ONLY the conclusion paragraph(s). No headline, no intro, no body. Begin directly with the closing paragraph.`;

const userPrompt = `Write the conclusion for this ${d.modeLabel}. It must close the article memorably and flow naturally from the main body above.`;

return [{ json: { ...d, stage3_system: systemPrompt, stage3_user: userPrompt } }];

const upstream = $('Build Stage 3 Prompt').first().json;
const conclusion = ($input.first().json.message?.content || $input.first().json.text || '').trim();
return [{ json: { ...upstream, conclusion } }];

const d = $input.first().json;

const fullArticle = [
  d.headline,
  '',
  d.introduction,
  '',
  d.mainBody,
  '',
  d.conclusion
].join('\n').trim();

function countWords(text) {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

return [{
  json: {
    success: true,
    sessionId: d.sessionId,
    publication: d.pubName,
    mode: d.mode,
    modeLabel: d.modeLabel,
    style_preset: d.stylePreset,
    tone: d.tone,
    audience: d.audienceLabel,
    confidence: d.confidence,
    article: {
      headline:     d.headline,
      introduction: d.introduction,
      main_body:    d.mainBody,
      conclusion:   d.conclusion,
      full_article: fullArticle,
      seo_keywords: d.seoKeywords
    },
    meta: {
      word_count_target:    d.wordCount,
      word_count_actual:    countWords(fullArticle),
      word_count_headline:  countWords(d.headline),
      word_count_intro:     countWords(d.introduction),
      word_count_body:      countWords(d.mainBody),
      word_count_conclusion:countWords(d.conclusion),
      generated_at:         d.timestamp,
      pipeline: '3-stage'
    }
  }
}];
